nginx_site:
server {
    listen 80;
    listen [::]:80;
    server_name axix.cc www.axix.cc;
    return 301 https://$host$request_uri;
}

server {
    # http2: 单连接多路复用，跨国高延迟链路下 46 个 css/js 并行加载的关键
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name axix.cc www.axix.cc;

    ssl_certificate /etc/letsencrypt/live/axix.cc/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/axix.cc/privkey.pem;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:le_nginx_SSL:10m;
    ssl_session_timeout 1440m;
    ssl_session_tickets off;

    # gzip 压缩
    gzip on;
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_min_length 1024;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript image/svg+xml;

    # 静态资源长期缓存（nginx 直出，绕过 node 代理，immutable 避免重复校验）
    location /assets/ {
        root /opt/wg-platform/public;
        expires 30d;
        add_header Cache-Control "public, max-age=2592000, s-maxage=2592000, immutable";
        access_log off;
    }

    location /styles/ {
        root /opt/wg-platform/public;
        expires 30d;
        add_header Cache-Control "public, max-age=2592000, s-maxage=2592000, immutable";
        access_log off;
    }

    location /js/ {
        root /opt/wg-platform/public;
        expires 30d;
        add_header Cache-Control "public, max-age=2592000, s-maxage=2592000, immutable";
        access_log off;
    }

    location /vendor/ {
        root /opt/wg-platform/public;
        expires 30d;
        add_header Cache-Control "public, max-age=2592000, s-maxage=2592000, immutable";
        access_log off;
    }

    location = /favicon.svg {
        root /opt/wg-platform/public;
        expires 30d;
        add_header Cache-Control "public, max-age=2592000, s-maxage=2592000, immutable";
        access_log off;
    }

    location /.well-known/acme-challenge/ {
        root /var/www/html;
    }

    location / {
        proxy_pass http://127.0.0.1:8082;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header CF-Connecting-IP $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
        client_max_body_size 20m;
    }
}

